    cols = len(grid[0])

    # Create output grid as copy of input
    output = [row[:] for row in grid]

    # Find the template rectangle (the one filled with 1s)
    # Find all 1s and determine bounding box
    ones_positions = []
    fours_positions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                ones_positions.append((r, c))
            elif grid[r][c] == 4:
                fours_positions.append((r, c))

    if not ones_positions:
        return output

    # Find bounding box of 1s
    min_r = min(r for r, c in ones_positions)
    max_r = max(r for r, c in ones_positions)
    min_c = min(c for r, c in ones_positions)
    max_c = max(c for r, c in ones_positions)

    # Verify it's a solid rectangle of 1s
    template_height = max_r - min_r + 1
    template_width = max_c - min_c + 1

    # Get internal 4s pattern (relative to top-left of template)
    internal_fours = []
    for r, c in fours_positions:
        if min_r <= r <= max_r and min_c <= c <= max_c:
            internal_fours.append((r - min_r, c - min_c))

    # Get external 4s
    external_fours = []
    for r, c in fours_positions:
        if not (min_r <= r <= max_r and min_c <= c <= max_c):
            external_fours.append((r, c))

    if not internal_fours or not external_fours:
        return output

